result:
.flex-box{
	display flex
	align-items center
	justify-content space-between
	padding 0 10px
	height 60px
	.iconfont{
		color: #999;
		font-size: 15px;
		margin-left: 10px;
	}
	.right{
		display flex
		align-items center
		margin-left: 10px;
	}
	.left{
		display flex
		align-items center
		.img-box,.empty-box{
			width 46px
			height 46px
			border-radius 50%
			img{
				width 100%
				height 100%
				border-radius 50%
			}
		}
		.name{
			margin-left 10px
			font-size 15px
			color #333
		}
	}
	.btn{
		width:56px;
		height:28px;
		border:1px solid #E93323;
		opacity:1;
		border-radius:25px;
		color #E93323
		font-size 12px
		text-align center
		line-height 28px
	}
	.iconfont-diy{
		font-size 20px
	}
}
